/**
 * GitHubBrain — Pushes generated files to a GitHub repo via GitHub API.
 * Uses GitHub REST API (user's token) — no AI.
 */

import { Brain, BrainContext } from '../../base/Brain'
import type { GeneratedFile } from '../../build/implementation/FileGeneratorBrain'

export interface GitHubBrainInput {
  files: GeneratedFile[]
  projectName: string
  description: string
  githubToken?: string
  githubUsername?: string
  makePrivate?: boolean
}

export interface GitHubBrainOutput {
  pushed: boolean
  repoUrl: string | null
  repoName: string | null
  filesCommitted: number
  error: string | null
  skipped: boolean
}

export class GitHubBrain extends Brain<GitHubBrainInput, GitHubBrainOutput> {
  readonly brainName = 'GitHubBrain'
  readonly orchestratorName = 'DeliveryOrchestrator'
  readonly engineName = 'IntelligenceEngine'
  readonly usesAI = false

  protected async process(input: GitHubBrainInput, _ctx: BrainContext): Promise<GitHubBrainOutput> {
    const { files, projectName, description, githubToken, githubUsername, makePrivate = true } = input

    // Skip if no token provided
    if (!githubToken || !githubUsername) {
      return { pushed: false, repoUrl: null, repoName: null, filesCommitted: 0, error: null, skipped: true }
    }

    const repoName = projectName.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '')
    const headers = {
      'Authorization': `Bearer ${githubToken}`,
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json',
    }

    try {
      // Create repo
      const createRes = await fetch('https://api.github.com/user/repos', {
        method: 'POST',
        headers,
        body: JSON.stringify({
          name: repoName,
          description: description.slice(0, 255),
          private: makePrivate,
          auto_init: false,
        }),
      })

      if (!createRes.ok) {
        const err = await createRes.json() as { message?: string }
        return { pushed: false, repoUrl: null, repoName, filesCommitted: 0, error: err.message ?? 'Failed to create repo', skipped: false }
      }

      // Push files in batches using tree API
      // First, create a tree with all files
      const tree = files.slice(0, 50).map(f => ({
        path: f.path,
        mode: '100644',
        type: 'blob',
        content: f.content,
      }))

      const treeRes = await fetch(`https://api.github.com/repos/${githubUsername}/${repoName}/git/trees`, {
        method: 'POST',
        headers,
        body: JSON.stringify({ tree }),
      })

      if (!treeRes.ok) {
        return { pushed: false, repoUrl: `https://github.com/${githubUsername}/${repoName}`, repoName, filesCommitted: 0, error: 'Failed to create file tree', skipped: false }
      }

      const treeData = await treeRes.json() as { sha: string }

      // Create commit
      const commitRes = await fetch(`https://api.github.com/repos/${githubUsername}/${repoName}/git/commits`, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          message: 'Initial commit — generated by Arivarangam AI',
          tree: treeData.sha,
          parents: [],
        }),
      })

      if (!commitRes.ok) {
        return { pushed: false, repoUrl: `https://github.com/${githubUsername}/${repoName}`, repoName, filesCommitted: 0, error: 'Failed to create commit', skipped: false }
      }

      const commitData = await commitRes.json() as { sha: string }

      // Update HEAD
      await fetch(`https://api.github.com/repos/${githubUsername}/${repoName}/git/refs`, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          ref: 'refs/heads/main',
          sha: commitData.sha,
        }),
      })

      return {
        pushed: true,
        repoUrl: `https://github.com/${githubUsername}/${repoName}`,
        repoName,
        filesCommitted: Math.min(files.length, 50),
        error: null,
        skipped: false,
      }
    } catch (err) {
      return {
        pushed: false,
        repoUrl: null,
        repoName,
        filesCommitted: 0,
        error: err instanceof Error ? err.message : 'GitHub push failed',
        skipped: false,
      }
    }
  }

  protected fallback(_: GitHubBrainInput): GitHubBrainOutput {
    return { pushed: false, repoUrl: null, repoName: null, filesCommitted: 0, error: null, skipped: true }
  }
}
